INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(49711, 'Isaiah 11:11', 'Isaiah', 11, 11, 'کله چې هغه ورځ راشي نو څښتن به یوځل بیا خپل لاس اوچت کړي او خپل پاتې خلک به چې په اشور، مصر، فتروس، ایتوپیا، عیلام، بابل او حمات په هېوادونو او د مدیترانې د بحیرې په غاړو او جزیرو کې دي، بېرته راولي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah11_verse_11.mp3', '', 1761754199, 1761754199),
(49712, 'Isaiah 11:12', 'Isaiah', 11, 12, 'څښتن به د نښې په توګه د قومونو په منځ کې یو بیرغ ورپوي او د نړۍ د څلورو کنجونو څخه به جلاوطني خواره واره اسراییلیان او یهودیان بېرته راولي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah11_verse_12.mp3', '', 1761754199, 1761754199),
(49713, 'Isaiah 11:13', 'Isaiah', 11, 13, 'د اسراییلیانو حسادت به د یهودا سره پای ته ورسیږي او یهودا به اسراییلیان ونه ځوروي او هغوی به نور د اسراییلیانو له خوا ونه ځورول شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah11_verse_13.mp3', '', 1761754199, 1761754199),
(49714, 'Isaiah 11:14', 'Isaiah', 11, 14, 'هغوی به په ګډه د لوېدیځ له خوا په فلسطینیانو حمله وکړي او هغه خلک به لوټ کړي چې ختیځ خواته اوسیږي. هغوی به د ادوم او موآب خلکو ته ماتې ورکړي او د عمون خلک به د هغوی اطاعت کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah11_verse_14.mp3', '', 1761754199, 1761754199),
(49715, 'Isaiah 11:15', 'Isaiah', 11, 15, 'څښتن به د سرې بحیرې خلیج وچ کړي. هغه به خپل لاس د فرات د سیند خواته اوچت کړي او دا سیند به د یو سوځوونکي باد سره په اوو ویالو باندې ووېشي، ترڅو هرڅوک وکولای شي په اسانۍ سره په پښو د هغه نه تېر شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah11_verse_15.mp3', '', 1761754199, 1761754199),
(49716, 'Isaiah 11:16', 'Isaiah', 11, 16, 'د څښتن د قوم نه د هغو خلکو دپاره چې ژوندي پاتې شوي دي، د اشور نه به د وتلو لویه لاره جوړه شي لکه د هغوی د نیکونو په شان چې د مصر نه وتل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah11_verse_16.mp3', '', 1761754199, 1761754199),
(49717, 'Jonah 1:1', 'Jonah', 1, 1, 'یوه ورځ څښتن د امتای زوی یونس ته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jonah1_verse_1.mp3', '', 1761754199, 1761754199),
(49718, 'Jonah 1:2', 'Jonah', 1, 2, '«د نینوا لوی ښار ته لاړ شه او په ضد یې وعظ وکړه. ځکه ما ولیدل چې د هغه ځای خلک څومره بدکاره دي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jonah1_verse_2.mp3', '', 1761754199, 1761754199),
(49719, 'Jonah 1:3', 'Jonah', 1, 3, 'خو یونس په بلې خوا روان شو، په دې خاطر چې له څښتن څخه وتښتي. هغه یافا ته لاړ او هلته یې یوه کشتۍ ولیدله چې هسپانیی ته روانه وه. هغه خپله کرایه ورکړه او د کشتیوانانو سره سپور شو چې هسپانیې ته سفر وکړي او د څښتن څخه لېرې شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jonah1_verse_3.mp3', '', 1761754199, 1761754199),
(49720, 'Jonah 1:4', 'Jonah', 1, 4, 'خو څښتن په بحیرې باندې یو قوي باد نازل کړ او دا توفان دومره تېز ؤ چې هغه کشتۍ د ماتېدلو په خطر کې وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jonah1_verse_4.mp3', '', 1761754199, 1761754199),
(49721, 'Jonah 1:5', 'Jonah', 1, 5, 'ټول کشتیوانان ووېرېدل او هر یو خپل خدای ته فریاد وکړ. هغوی بارونه بحیرې ته ورګوزار کړ، ترڅو کشتۍ سپکه شي. خو یونس د کشتۍ دننه لاندې ننوتی ؤ او هلته په درانه خوب ویده ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jonah1_verse_5.mp3', '', 1761754199, 1761754199),
(49722, 'Jonah 1:6', 'Jonah', 1, 6, 'د کشتۍ مشر هغه ته ورغی او ورته ویې ویل: «څنګه ویده پروت یې؟ پاڅه او خپل خدای ته فریاد وکړه! کېدای شي چې هغه په مونږ باندې رحم وکړي او زمونږ ژوند وژغوري.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jonah1_verse_6.mp3', '', 1761754199, 1761754199),
(49723, 'Jonah 1:7', 'Jonah', 1, 7, 'بیا هغو کشتیوانانو یو بل ته وویل: «راځئ چې پچه واچوو چې دا معلومه کړو چې دا بلا د چا له امله په مونږ باندې راغلې ده.» هغوی پچه واچوله او پچه د یونس په نوم وختله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jonah1_verse_7.mp3', '', 1761754199, 1761754199),
(49724, 'Jonah 1:8', 'Jonah', 1, 8, 'بیا هغوی د هغه څخه پوښتنې وکړې: «مونږ ته ووایه چې په دې کې څوک ملامته دی چې دا بلا یې په مونږ باندې راوستې ده؟ ته څه کار کوې؟ د کوم وطن څخه راغلی یې؟ د کوم قوم څخه یې؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jonah1_verse_8.mp3', '', 1761754199, 1761754199),
(49725, 'Jonah 1:9', 'Jonah', 1, 9, 'هغه په ځواب کې وویل: «زه یو عبرانی یم او د څښتن، د اسمان د خدای چې بحیره او ځمکه یې جوړ کړي دي، عبادت کوم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jonah1_verse_9.mp3', '', 1761754199, 1761754199),
(49726, 'Jonah 1:10', 'Jonah', 1, 10, 'یونس هغوی ته وویل چې زه د څښتن څخه تښتم. نو کشتیوانان ډېر ووېرېدل او ورته ویې ویل: «دا تا څه وکړل!»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jonah1_verse_10.mp3', '', 1761754199, 1761754199),
(49727, 'Jonah 1:11', 'Jonah', 1, 11, 'توفان نور هم زیاتېده، نو هغوی د هغه څخه پوښتنه وکړه: «مونږ تا سره څه وکړو چې توفان ودریږي؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jonah1_verse_11.mp3', '', 1761754199, 1761754199),
(49728, 'Jonah 1:12', 'Jonah', 1, 12, 'هغه په ځواب کې وویل: «ما پورته کړئ او بحیرې ته مې ورګوزار کړئ، نو توفان به غلی شي. ځکه زه پوهېږم چې دا لوی توفان زما له امله په تاسو باندې راغلی دی.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jonah1_verse_12.mp3', '', 1761754199, 1761754199),
(49729, 'Jonah 1:13', 'Jonah', 1, 13, 'د دې په ځای کشتیوانانو هڅه وکړه چې کشتۍ وچې ته وباسي. هغوی د خپل ټول قوت څخه کار واخیست، خو توفان نور هم زیاتېده او هغوی څه ونه شو کولی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jonah1_verse_13.mp3', '', 1761754199, 1761754199),
(49730, 'Jonah 1:14', 'Jonah', 1, 14, 'بیا هغوی څښتن ته فریاد وکړ: «ای څښتنه، د دغه سړي د وژلو په خاطر مونږ مه مړه کوه او د هغه د مرګ مسوولیت زمونږ په غاړه مه اچوه، ځکه چې تا ای څښتنه، په خپله خوښه دا کار کړی دی.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jonah1_verse_14.mp3', '', 1761754199, 1761754199),
(49731, 'Jonah 1:15', 'Jonah', 1, 15, 'بیا هغوی یونس پورته کړ او بحیرې ته یې ورګوزار کړ او توفان سمدستي غلی شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jonah1_verse_15.mp3', '', 1761754199, 1761754199),
(49732, 'Jonah 1:16', 'Jonah', 1, 16, 'په دې کار هغه سړي د څښتن څخه ډېر ووېرېدل او هغوی څښتن ته قرباني وړاندې کړه او نذرونه یې ورکړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jonah1_verse_16.mp3', '', 1761754199, 1761754199),
(49733, 'Jonah 1:17', 'Jonah', 1, 17, 'څښتن یو لوی ماهي ولېږه چې یونس ژوندی تیر کړي او یونس درې ورځې او درې شپې د ماهي په ګېډه کې ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jonah1_verse_17.mp3', '', 1761754199, 1761754199),
(49734, 'Songofsongs 5:1', 'Songofsongs', 5, 1, 'زما دُنيا، زما ناوې، زۀ په خپل باغ کښې داخل شوے يمه. زۀ د مُر چيړ او خوشبوداره مصالحې راټولومه. ما خپل ګبين د شاتو سره وخوړلونه، او زۀ خپل پئ او مے څښمه. ښځې اے عاشقانو، وخورئ او وڅښئينه. او د مينې نه مست شئينه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs5_verse_1.mp3', '', 1761754199, 1761754199),
(49735, 'Songofsongs 5:2', 'Songofsongs', 5, 2, 'زۀ اودۀ ومه خو زما زړۀ بېدار وونه، غوږ شه. زما جانان ور ټکوينه. ”زما د زړۀ دُنيا او محبوبې ور کولاو کړه، زما ګوګوشتکې، زما بې‌عېبه مينې. محبوب زما سر په شبنم باندې لوند دېنه، او د شپې پرخې مې وېښتۀ لوندۀ کړى دينه.“ محبوبه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs5_verse_2.mp3', '', 1761754199, 1761754199),
(49736, 'Songofsongs 5:3', 'Songofsongs', 5, 3, 'ما خو جامې ويستلې دينه، نو دا بيا دوباره واچوم څۀ؟ ما خپلې پښې وينځلې دينه، بيا دا دوباره په خاورو ګنده کړم څۀ؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs5_verse_3.mp3', '', 1761754199, 1761754199),
(49737, 'Songofsongs 5:4', 'Songofsongs', 5, 4, 'زما جانان خپل لاس په ور کښې راوږد کړونه، نو زما زړۀ د هغۀ دپاره په درزېدو شونه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs5_verse_4.mp3', '', 1761754199, 1761754199),
(49738, 'Songofsongs 5:5', 'Songofsongs', 5, 5, 'نو زۀ راپاڅېدم چې خپل جانان ته ور کولاو کړمه. زما د لاسونو نه عطر په څڅېدو شونه. زما د ګوتو نه د مُر چيړ په څڅېدو شونه کله چې ما د ور کُنډه راښکله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs5_verse_5.mp3', '', 1761754199, 1761754199),
(49739, 'Songofsongs 5:6', 'Songofsongs', 5, 6, 'ما خپل جانان ته ور کولاو کړونه، خو هغه بيا تلے وو، نو زۀ سخته پرېشانه شومه، ما هغه ولټولو، خو هغه مې پېدا نۀ کړونه، ما هغۀ ته آواز وکړونه، خو هغۀ ما ته جواب رانۀ کړونه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs5_verse_6.mp3', '', 1761754199, 1761754199),
(49740, 'Songofsongs 5:7', 'Songofsongs', 5, 7, 'کومو څوکيدارانو چې په ښار کښې ګشت کولونه نو هغوئ زۀ ونيولم، هغوئ زۀ ووهلمه او په وهلو يې تکه شنه کړمه، او د ښار د دېوالونو چوکيدارانو زما د مخ نه پلو اوچت کړونه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs5_verse_7.mp3', '', 1761754199, 1761754199),
(49741, 'Songofsongs 5:8', 'Songofsongs', 5, 8, 'اے د يروشلم ښځو، ما سره دا وعده وکړئينه، کۀ چرې تاسو زما جانان وليدلو، هغۀ ته ووائينه چې زۀ د هغۀ د مينې په وجه کمزورې شوې يمه. ښځې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs5_verse_8.mp3', '', 1761754199, 1761754199),
(49742, 'Songofsongs 5:9', 'Songofsongs', 5, 9, 'اے په ټولو پېغلو کښې ښائسته جينۍ، ستا جانان د نورو سړو نه کوم خاص خصوصيت لرينه؟ په هغۀ کښې داسې څۀ خاص دينه، چې مونږ تا سره دا لوظ وکړونه؟ محبوبه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs5_verse_9.mp3', '', 1761754199, 1761754199),
(49743, 'Songofsongs 5:10', 'Songofsongs', 5, 10, 'زما جانان سور سپين دېنه، او په لسو زرو کښې د ټولو نه اعلىٰ دېنه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs5_verse_10.mp3', '', 1761754199, 1761754199),
(49744, 'Songofsongs 5:11', 'Songofsongs', 5, 11, 'د هغۀ سر د سوچه سرو زرو دېنه، د هغۀ وېښتۀ وَل وَل دينه، او لکه د کارغۀ په شان تور دېنه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs5_verse_11.mp3', '', 1761754199, 1761754199),
(49745, 'Songofsongs 5:12', 'Songofsongs', 5, 12, 'د هغۀ سترګې د ګوګوشتکو په شان دينه چې د اوبو د چينو په خوا کښې وينه سپينې ګوګوشتکې لکه د پئيو په شان چې د تالاب په خوا کښې ناستې وينه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs5_verse_12.mp3', '', 1761754199, 1761754199),
(49746, 'Songofsongs 5:13', 'Songofsongs', 5, 13, 'د هغۀ اننګى د باغ په شان دينه، چې د خوشبودارو بوټو نه ډک وينه. د هغۀ شونډې د لاله د ګل په شان دينه، لکه چې د مُر په چيړ خوشبويه شوې وينه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs5_verse_13.mp3', '', 1761754199, 1761754199),
(49747, 'Songofsongs 5:14', 'Songofsongs', 5, 14, 'د هغۀ لاسونه د سرو زرو سيخونه دينه، چې په دې کښې قيمتى کاڼى لګېدلى وينه. د هغۀ بدن لکه د هاتى د غاښونو په شان سپين دېنه، او چې په کښې نيلم کاڼى لګېدلى وينه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs5_verse_14.mp3', '', 1761754199, 1761754199),
(49748, 'Songofsongs 5:15', 'Songofsongs', 5, 15, 'د هغۀ پښې د سنګِ مرمرو د ستنو په شان دينه چې په سرو زرو کښې لګولے شوې وينه. د هغۀ شکل د لبنان د غرونو د خاص دِيار په شان ښکارينه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs5_verse_15.mp3', '', 1761754199, 1761754199),
(49749, 'Songofsongs 5:16', 'Songofsongs', 5, 16, 'هغه ډېره خوږه خولۀ لرينه، هغه په هر لحاظ زړۀ راښکونکے دېنه، نو، اے د يروشلم ښځو، زما جانان او زما آشنا دغه شان دېنه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs5_verse_16.mp3', '', 1761754199, 1761754199),
(49750, 'Ecclesiastes 9:1', 'Ecclesiastes', 9, 1, 'نو ما په دې ټولو کارونو باندې فکر وکړ، ترڅو دا هرڅه وڅېړم. زه دې نتیجې ته ورسېدم چې نېکان او هوښیاران او د هغوی کارونه د خدای په لاس کې دي. دا چې له انسان سره مینه کیږي یا کرکه، خو هېڅوک په دې نه پوهیږي چې د انسان په راتلونکې کې به څه پېښیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes9_verse_1.mp3', '', 1761754199, 1761754199),
(49751, 'Ecclesiastes 9:2', 'Ecclesiastes', 9, 2, 'څه چې په یو پېښیږي هغه په بل هم پېښیږي نو د ټولو پای یو دی څوک چې نېک کاره وي او څوک چې بدکاره وي څوک چې پوره پاک وي او څوک چې ناپاک وي څوک چې قرباني ورکوي او څوک چې قرباني نه ورکوي څه چې له ښه سړي سره کیږي هغه د ګناهکار سره هم کیږي څه چې له قسم خوړونکي سره کیږي هغه له قسم څخه وېرېدونکي سره هم کیږي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes9_verse_2.mp3', '', 1761754199, 1761754199),
(49752, 'Ecclesiastes 9:3', 'Ecclesiastes', 9, 3, 'دا بله بدبختي ده چې د اسمان لاندې په هر شي باندې پېښیږي، چې د ټولو پای یو دی. همدا شان د انسانانو زړونه له شرارت نه ډک دي، او ترڅو چې ژوندي دي په زړونو کې یې جهالت وي، بیا دوی له مړو سره یوځای کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes9_verse_3.mp3', '', 1761754199, 1761754199),
(49753, 'Ecclesiastes 9:4', 'Ecclesiastes', 9, 4, 'په یقین سره څوک چې د ژوندیو په منځ کې دی هغه په دې تمه دی چې له مړ زمري نه ژوندی سپی ښه دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes9_verse_4.mp3', '', 1761754199, 1761754199),
(49754, 'Ecclesiastes 9:5', 'Ecclesiastes', 9, 5, 'ځکه ژوندي په دې پوهیږي چې دوی به مړه شي، خو مړي په دې هېڅ نه پوهیږي. مړي نور هېڅ اجوره نه لري او حتی د هغوی یاد له منځه ځي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes9_verse_5.mp3', '', 1761754199, 1761754199),
(49755, 'Ecclesiastes 9:6', 'Ecclesiastes', 9, 6, 'هغه څه چې هغوی ورسره مینه لرله او له هغه څه نه چې هغوی ترې کرکه کوله او له هغه چا سره چې هغوی سیالي لرله هغه پخوا له منځه تللي دي او دوی نور هېڅکله په هغه څه کې برخه نه لري چې د اسمان لاندې تر‌سره کیږي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes9_verse_6.mp3', '', 1761754199, 1761754199),
(49756, 'Ecclesiastes 9:7', 'Ecclesiastes', 9, 7, 'نو ځه او خپل خواړه په خوښۍ سره وخوره، او خپل شراب په خوشحاله زړه وڅښه، ځکه چې خدای لا پخوا ستا له دې کارونو څخه راضي او خوشحاله دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes9_verse_7.mp3', '', 1761754199, 1761754199),
(49757, 'Ecclesiastes 9:8', 'Ecclesiastes', 9, 8, 'ستا جامې دې د ښادیو دپاره تل سپینې وي او خپل سر په قیمتي تېلو غوړوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes9_verse_8.mp3', '', 1761754199, 1761754199),
(49758, 'Ecclesiastes 9:9', 'Ecclesiastes', 9, 9, 'د خپل لوګي او پوکي په شان ژوند په موده کې له خپلې ګرانې ښځې سره د ژوند نه خوند واخله. دا خدای دی چې دا د لوګي او پوکي په څېر ورځې یې تاته د اسمان لاندې درکړې دي. ځکه چې دا خوشحالي ستا د ژوند او د هغه زیار او زحمت برخه ده چې د یو مزدور په څېر یې د اسمان لاندې وباسې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes9_verse_9.mp3', '', 1761754199, 1761754199),
(49759, 'Ecclesiastes 9:10', 'Ecclesiastes', 9, 10, 'هر هغه څه چې ته په خپلو لاسونو تر‌سره کوې هغه په خپل ټول قوت سره تر‌سره کړه، ځکه چې په قبر کې نه کار شته، نه نقشه شته او نه هم پوهه او حکمت شته، هغه ځای چې ته به په پای کې ورته ورځې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes9_verse_10.mp3', '', 1761754199, 1761754199),
(49760, 'Ecclesiastes 9:11', 'Ecclesiastes', 9, 11, 'یوځل بیا ما د اسمان لاندې ولیدل: منزل ته زر رسېدل تل د تېزو منډې وهونکو په برخه نه وي د جګړې ګټل تل د قوي جنګیالیو په برخه نه وي د ژوند د وسیلو تر‌لاسه کول هم تل د هوښیارانو په برخه نه وي د شتمنۍ ګټل هم تل د عقلمندو په برخه نه وي او نه هم بری تل د پوهانو په برخه وي ځکه وخت او بخت به د دې هر یو انجام وي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes9_verse_11.mp3', '', 1761754199, 1761754199),
(49761, 'Ecclesiastes 9:12', 'Ecclesiastes', 9, 12, 'دا هم حقیقت لري چې هېڅوک له دغه ټاکل شوي وخت څخه خبر نه دی! لکه ماهي چې په جال کې ونیول شي یا مرغۍ چې په لومه کې راونیول شي نو انسانان به هم همداسې په دام کې راګېر شي او بدبختي به ناڅاپه په هغوی باندې نازله شي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes9_verse_12.mp3', '', 1761754199, 1761754199),
(49762, 'Ecclesiastes 9:13', 'Ecclesiastes', 9, 13, 'ما د اسمان لاندې د حکمت په اړه دا هم لیدلي دي چې په ما باندې یې ډېره اغېزه کړې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes9_verse_13.mp3', '', 1761754199, 1761754199),
(49763, 'Ecclesiastes 9:14', 'Ecclesiastes', 9, 14, 'یو کوچنی ښار ؤ چې یو څو سړي په کې اوسېدل، او یو قوي پاچا پرې حمله وکړه، هغه یې کلابند کړ او لښکر یې د هغه ښار د دېوالونو د ماتولو دپاره قوي وسیلې جوړې کړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes9_verse_14.mp3', '', 1761754199, 1761754199),
(49764, 'Ecclesiastes 9:15', 'Ecclesiastes', 9, 15, 'خو په هغه ښار کې یو غریب خو هوښیار سړی پیدا شو چې په خپل حکمت سره یې هغه ښار وژغوره. خو هغه غریب سړی هم د خلکو له خوا هېر شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes9_verse_15.mp3', '', 1761754199, 1761754199),
(49765, 'Ecclesiastes 9:16', 'Ecclesiastes', 9, 16, 'نو زه دې نتیجې ته ورسېدم چې له قوت نه حکمت ښه دی خو د غریب سړي حکمت ته په سپکه سترګه کتل کیږي او هېڅکله د هغه مشورو ته غوږ نه نیول کیږي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes9_verse_16.mp3', '', 1761754199, 1761754199),
(49766, 'Ecclesiastes 9:17', 'Ecclesiastes', 9, 17, 'د هوښیارانو نرمې خبرې د حاکم له هغو چیغو نه زر اورېدل کیږي چې د احمقانو په منځ کې په لوړ اواز ویل کیږي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes9_verse_17.mp3', '', 1761754199, 1761754199),
(49767, 'Ecclesiastes 9:18', 'Ecclesiastes', 9, 18, 'له جنګي وسلو نه حکمت ښه دی خو یو ګناهکار ډېر څه له منځه وړي چې هغه ښه دي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes9_verse_18.mp3', '', 1761754199, 1761754199),
(49768, 'Isaiah 26:1', 'Isaiah', 26, 1, 'هغه ورځ راتلونکې ده چې خلک به د یهودا په خاوره کې دا روحاني سندره ووایي: دی قوي زمونږه ښار ځکه چاپېر دي له هغه نه دېوالونه د خدای د خلاصون', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah26_verse_1.mp3', '', 1761754199, 1761754199),
(49769, 'Isaiah 26:2', 'Isaiah', 26, 2, 'دروازې د ښار کړئ خلاصې ترڅو راننوځي نېک قوم هغه قوم چې څښتن ته وفادار دی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah26_verse_2.mp3', '', 1761754199, 1761754199),
(49770, 'Isaiah 26:3', 'Isaiah', 26, 3, 'ای څښتنه، پوره امن کې ساتې ته هغه څوک چې لري اراده ټینګه ځکه په تا باندې توکل لري', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah26_verse_3.mp3', '', 1761754199, 1761754199),
(49771, 'Isaiah 26:4', 'Isaiah', 26, 4, 'تل په څښتن باندې توکل وکړئ ځکه تلپاتې غر دی څښتن خدای زمونږه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah26_verse_4.mp3', '', 1761754199, 1761754199),
(49772, 'Isaiah 26:5', 'Isaiah', 26, 5, 'هغه څوک چې وو مغرور او کبرجن هغوی یې کړل خوار او ذلیل هغه ښارونه هغه وران کړل چې وو قوي او لوړو ځایونو کې وو او کړل یې د خاورو سره خاورې هغه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah26_verse_5.mp3', '', 1761754199, 1761754199),
(49773, 'Isaiah 26:6', 'Isaiah', 26, 6, 'اوس په وران شوي ښار کې ګرځي مظلومان او تر پښو لاندې کوي غریبان خلک', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah26_verse_6.mp3', '', 1761754199, 1761754199),
(49774, 'Isaiah 26:7', 'Isaiah', 26, 7, 'لاره سمه ده د نېکو خلکو ای څښتنه، هواروې لاره د نېکو خلکو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah26_verse_7.mp3', '', 1761754199, 1761754199),
(49775, 'Isaiah 26:8', 'Isaiah', 26, 8, 'ای څښتنه، مونږ کوو ستا د حکمونو اطاعت او ده تاته زمونږ هیله زمونږه زړونه غواړي چې ژوندی وساتو ستا نوم او یاد', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah26_verse_8.mp3', '', 1761754199, 1761754199),
(49776, 'Isaiah 26:9', 'Isaiah', 26, 9, 'زه ټوله شپه تاته لېوال یمه د سهار له خوا زه یمه ستا لټون کې د زړه له کومي کله چې ته کړې قضاوت د نړۍ د اوسېدونکو هغه وخت به خلک پوه شي په انصاف او عدالت باندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah26_verse_9.mp3', '', 1761754199, 1761754199),
(49777, 'Isaiah 26:10', 'Isaiah', 26, 10, 'که مهرباني هم وشي په بدکارانو باندې خو دوی نه زده کوي هېڅکله چې وکړي نېک کار هغوی دوام ورکوي د انصاف ځمکه کې هم بدو کارونو ته خپل او د څښتن لویي او جلال نه ویني', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah26_verse_10.mp3', '', 1761754199, 1761754199),
(49778, 'Isaiah 26:11', 'Isaiah', 26, 11, 'ای څښتنه، نه پوهیږي دښمنان ستا چې اوچت شوی دی ستا لاس د هغوی د سزا دپاره هغوی ته وښایه چې ته لرې غیرت د خپل قوم دپاره ترڅو وشرمیږي دوی او وسوځیږي ستا د قهر اور کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah26_verse_11.mp3', '', 1761754199, 1761754199),
(49779, 'Isaiah 26:12', 'Isaiah', 26, 12, 'ای څښتنه، ته به راکړې ارامي مونږ ته ځکه زمونږ بریالیتوب دی ستا د کار نتیجه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah26_verse_12.mp3', '', 1761754199, 1761754199),
(49780, 'Isaiah 26:13', 'Isaiah', 26, 13, 'ای زمونږ څښتنه خدایه، په مونږ حکم کړی ډېرو واک لرونکو خو ته یوازېنی واک لرونکی او څښتن یې زمونږ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah26_verse_13.mp3', '', 1761754199, 1761754199),
(49781, 'Isaiah 26:14', 'Isaiah', 26, 14, 'خو اوس مړه شوي هغوی او راژوندي کیږي نه بیا ارواحګانې د هغوی نه راځي بېرته ځکه چې تا سزا ورکړې او تباه کړي دي دوی او له منځه وړی دې د هغوی نوم او نښان دی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah26_verse_14.mp3', '', 1761754199, 1761754199),
(49782, 'Isaiah 26:15', 'Isaiah', 26, 15, 'خو ای څښتنه، تا ډېر کړی دی خپل قوم پراخ کړی دې دی زمونږ هېواد او څرګنده کړې دې ده خپله لویي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah26_verse_15.mp3', '', 1761754199, 1761754199),
(49783, 'Isaiah 26:16', 'Isaiah', 26, 16, 'ای څښتنه، هغوی وکړله رجوع تا ته د کړاوونو وخت کې کله چې ورکړه تا هغوی ته سزا ستا حضور ته یې دعا وکړه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah26_verse_16.mp3', '', 1761754199, 1761754199),
(49784, 'Isaiah 26:17', 'Isaiah', 26, 17, 'ای څښتنه، تا په مونږه داسې چیغې ووهلې لکه یوه ښځه چې د ماشوم د زېږېدو په وخت کې له ډېره درده تاویږي راتاویږي او وهي چیغې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah26_verse_17.mp3', '', 1761754199, 1761754199),
(49785, 'Isaiah 26:18', 'Isaiah', 26, 18, 'لکه د ښځې د لنګون په وخت کې تاوېدو راتاوېدلو مونږ له درده خو څه مو ونه زېږول مونږ ورنه کړل ماشومان نړۍ ته او حاصل مو نه کړلو بری په ځمکه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah26_verse_18.mp3', '', 1761754199, 1761754199),
(49786, 'Isaiah 26:19', 'Isaiah', 26, 19, 'خو مړه شوي خلک به ستا بېرته راژوندي شي هغوی به پاڅي له قبرونو څخه چې په خاورو کې اوسیږي هغوی شي دې راویښ او ودې وایي د خوشحالۍ سندرې لکه چې څنګه تازه کوي ځمکه ځلېدونکې پرخه نو څښتن به راژوندي کړي هغه مړه شوي خلک', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah26_verse_19.mp3', '', 1761754199, 1761754199),
(49787, 'Isaiah 26:20', 'Isaiah', 26, 20, 'ای زما خلکو، خپلو کورونو ته لاړ شئ او خپلو ځانونو پسې دروازې وتړئ. د لږ وخت دپاره خپل ځانونه پټ کړئ ترڅو د څښتن قهر سوړ شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah26_verse_20.mp3', '', 1761754199, 1761754199),
(49788, 'Isaiah 26:21', 'Isaiah', 26, 21, 'ځکه وګورئ، څښتن د خپل استوګنځي څخه راروان دی چې د ځمکې خلکو ته د هغوی د ګناهونو په سبب سزا ورکړي. د کومو خلکو وینه چې د ځمکې په مخ تویه شوې ده هغه به ښکاره شي او نور به ځمکه د وژل شویو خلکو مړي نه پټوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah26_verse_21.mp3', '', 1761754199, 1761754199),
(49789, 'Genesis 46:1', 'Genesis', 46, 1, 'یعقوب چې هرڅه درلودل هغه یې واخیستل او بیرشبع ته لاړ او هلته یې د خپل پلار اسحاق خدای ته قربانۍ وړاندې کړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis46_verse_1.mp3', '', 1761754199, 1761754199),
(49790, 'Genesis 46:2', 'Genesis', 46, 2, 'خدای د یعقوب سره د شپې په رویا کې خبرې وکړې او ورته ویې ویل: «ای یعقوبه، ای یعقوبه!» هغه ځواب ورکړ: «زه حاضر یم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis46_verse_2.mp3', '', 1761754199, 1761754199),
(49791, 'Genesis 46:3', 'Genesis', 46, 3, 'هغه وویل: «زه خدای یم، ستا د پلار خدای. مصر ته د تللو څخه مه وېرېږه، ځکه چې هلته به ستا څخه یو لوی قوم جوړ کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis46_verse_3.mp3', '', 1761754199, 1761754199),
(49792, 'Genesis 46:4', 'Genesis', 46, 4, 'زه به ستا سره مصر ته لاړ شم او په یقین سره به ستا اولاده بېرته دې وطن ته راولم. کله چې ته مړ شوې، نو یوسف به دې ښخ کړي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis46_verse_4.mp3', '', 1761754199, 1761754199),
(49793, 'Genesis 46:5', 'Genesis', 46, 5, 'نو یعقوب د بیرشبع څخه روان شو. د هغه زامنو خپل پلار یعقوب، خپل اولادونه او خپلې ښځې واخیستلې او په هغو ګاډیو کې یې سپرې کړلې چې فرعون د هغوی د راوستلو دپاره لېږلې وې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis46_verse_5.mp3', '', 1761754199, 1761754199),
(49794, 'Genesis 46:6', 'Genesis', 46, 6, 'همدارنګه هغوی خپل حیوانات او شتمني چې په کنعان کې یې ګټلي وو، واخیستل او یعقوب او د هغه ټوله اولاده مصر ته لاړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis46_verse_6.mp3', '', 1761754199, 1761754199),
(49795, 'Genesis 46:7', 'Genesis', 46, 7, 'نو هغه د ځان سره خپل زامن، لمسیان، خپلې لورګانې، لمسیانې او خپله ټوله اولاده مصر ته بوتلل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis46_verse_7.mp3', '', 1761754199, 1761754199),
(49796, 'Genesis 46:8', 'Genesis', 46, 8, 'د یعقوب د کورنۍ غړي چې د هغه سره مصر ته راغلل دا دي: د یعقوب مشر زوی روبین.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis46_verse_8.mp3', '', 1761754199, 1761754199),
(49797, 'Genesis 46:9', 'Genesis', 46, 9, 'د روبین زامن: حنوک، فلو، حزرون او کرمي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis46_verse_9.mp3', '', 1761754199, 1761754199),
(49798, 'Genesis 46:10', 'Genesis', 46, 10, 'شمعون او د هغه زامن: یموییل، یامین، اوحد، یاکین، صوحر او شاوول د کنعانۍ ښځې زوی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis46_verse_10.mp3', '', 1761754199, 1761754199),
(49799, 'Genesis 46:11', 'Genesis', 46, 11, 'لاوي او د هغه زامن: جرشون، قهات او مراري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis46_verse_11.mp3', '', 1761754199, 1761754199),
(49800, 'Genesis 46:12', 'Genesis', 46, 12, 'یهودا او د هغه زامن: عیر، اونان، شیله، فارص او زارح. (خو عیر او اونان په کنعان کې مړه شوي وو.) د فارص زامن حصرون او حامول وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis46_verse_12.mp3', '', 1761754199, 1761754199),
(49801, 'Genesis 46:13', 'Genesis', 46, 13, 'یساکار او د هغه زامن: تولاع، فوه، یوب او شمرون.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis46_verse_13.mp3', '', 1761754199, 1761754199),
(49802, 'Genesis 46:14', 'Genesis', 46, 14, 'زبولون او د هغه زامن: سارد، ایلون او یاحلییل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis46_verse_14.mp3', '', 1761754199, 1761754199),
(49803, 'Genesis 46:15', 'Genesis', 46, 15, 'دا د لیه زامن وو چې په بین‌النهرین کې یې یعقوب ته وزېږول چې په هغو کې د هغې لور دینه هم شامله وه. د لیه د اولادې ټول شمېر دري دېرش تنه وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis46_verse_15.mp3', '', 1761754199, 1761754199),
(49804, 'Genesis 46:16', 'Genesis', 46, 16, 'جاد او د هغه زامن: صفیون، حجي، شوني، اصبون، عیري، ارودي او ارییلي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis46_verse_16.mp3', '', 1761754199, 1761754199),
(49805, 'Genesis 46:17', 'Genesis', 46, 17, 'اشیر او د هغه زامن: یمنه، یشوه، یشوي، بریعه او د هغوی خور سارح وه. او د بریعه زامن حابر او ملکییل وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis46_verse_17.mp3', '', 1761754199, 1761754199),
(49806, 'Genesis 46:18', 'Genesis', 46, 18, 'دغه شپاړس تنه د یعقوب اولاده وه چې د زلفې څخه پیدا شوي وو او زلفه هغه وینځه وه چې لابان خپلې لور لیه ته ورکړې وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis46_verse_18.mp3', '', 1761754199, 1761754199),
(49807, 'Genesis 46:19', 'Genesis', 46, 19, 'د یعقوب د ښځې راحیل زامن: یوسف او بنیامین.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis46_verse_19.mp3', '', 1761754199, 1761754199),
(49808, 'Genesis 46:20', 'Genesis', 46, 20, 'په مصر کې د اون د کاهن لور اسنات یوسف ته منسي او افرایم وزېږول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis46_verse_20.mp3', '', 1761754199, 1761754199),
(49809, 'Genesis 46:21', 'Genesis', 46, 21, 'بنیامین او د هغه زامن: بالع، باکر، اشبیل، جیرا، نعمان، ایحي، رش، مفیم، حفیم او آرد.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis46_verse_21.mp3', '', 1761754199, 1761754199),
(49810, 'Genesis 46:22', 'Genesis', 46, 22, 'دغه څوارلس تنه د یعقوب اولاده وه چې د راحیل څخه پیدا شوي وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis46_verse_22.mp3', '', 1761754199, 1761754199);